(1, 'Kolkata Central', 'Kolkata', '[\"700001\", \"700002\", \"700003\", \"700004\", \"700005\", \"700006\", \"700007\", \"700008\", \"700009\", \"700010\", \"700011\", \"700012\", \"700013\", \"700014\", \"700015\", \"700016\", \"700017\", \"700018\", \"700019\", \"700020\", \"700021\", \"700022\", \"700023\", \"700024\", \"700025\", \"700026\", \"700027\", \"700028\", \"700029\", \"700030\", \"700031\", \"700032\", \"700033\", \"700034\", \"700035\", \"700036\", \"700037\", \"700038\", \"700040\", \"700041\", \"700042\", \"700043\", \"700044\", \"700045\", \"700046\", \"700047\", \"700050\", \"700052\", \"700053\", \"700054\", \"700060\", \"700061\", \"700062\", \"700063\", \"700065\", \"700066\", \"700067\", \"700068\", \"700069\", \"700071\", \"700072\", \"700073\", \"700074\", \"700075\", \"700077\", \"700078\", \"700080\", \"700082\", \"700085\", \"700086\", \"700087\", \"700088\", \"700089\", \"700090\", \"700092\", \"700094\", \"700095\", \"700099\", \"700100\", \"700107\", \"700108\"]', 1, NULL, '2026-11-25 11:10:34', '2026-11-25 11:10:34');
INSERT INTO `service_categories` (`id`, `name`, `slug`, `tagline`, `description`, `icon`, `starting_price`, `price_unit`, `highlights`, `form_fields`, `is_active`, `is_featured`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'Private Chef', 'private-chef', 'A professional chef cooks at your home', 'From intimate dinners to family celebrations, a private chef plans the menu, cooks, serves and cleans up.', 'chef', 1999.00, 'per event', '[\"Custom menu for your event\", \"Shopping, cooking & serving\", \"Dietary needs handled\", \"Kitchen left spotless\"]', '[{\"key\": \"guest_count\", \"type\": \"number\", \"label\": \"Number of guests\", \"required\": true, \"placeholder\": \"e.g. 6\"}, {\"key\": \"meal\", \"type\": \"select\", \"label\": \"Occasion / meal\", \"options\": [\"Breakfast\", \"Lunch\", \"Dinner\", \"Party / celebration\", \"Daily cook (long term)\"], \"required\": false}, {\"key\": \"cuisine\", \"type\": \"multiselect\", \"label\": \"Cuisine preferences\", \"options\": [\"Indian\", \"Chinese\", \"Italian\", \"Continental\", \"Mexican\", \"Thai\"], \"required\": false}]', 1, 1, 5, '2026-11-25 07:56:08', '2026-11-25 07:56:10'),
(2, 'Electrician', 'electrician', 'Wiring, switches, fans, lights & MCB repairs', 'Certified electricians for everything from a faulty switch to complete house wiring. Safe, quick and fairly priced.', 'bolt', 149.00, 'per visit', '[\"Verified & trained electricians\", \"Switch, socket & MCB repair\", \"Fan, light & geyser installation\", \"30-day service warranty\"]', '[{\"key\": \"work_type\", \"type\": \"select\", \"label\": \"What do you need?\", \"options\": [\"Switch / socket repair\", \"Fan installation or repair\", \"Light / fixture installation\", \"MCB / fuse problem\", \"Wiring / rewiring\", \"Inverter / stabiliser\", \"Other\"], \"required\": true}, {\"key\": \"points\", \"type\": \"number\", \"label\": \"Number of points / items\", \"required\": false, \"placeholder\": \"e.g. 3\"}]', 1, 1, 1, '2026-11-25 07:56:10', '2026-11-25 09:36:09'),
(3, 'Plumber', 'plumber', 'Leaks, taps, blockages, tanks & bathroom fittings', 'Experienced plumbers who fix leaks, blockages and fittings the first time, with all tools carried.', 'wrench', 149.00, 'per visit', '[\"Leakage & blockage experts\", \"Tap, shower & flush repair\", \"Water tank & motor fitting\", \"Transparent pricing\"]', '[{\"key\": \"work_type\", \"type\": \"select\", \"label\": \"What do you need?\", \"options\": [\"Leakage repair\", \"Tap / shower / mixer\", \"Drain blockage\", \"Toilet / flush repair\", \"Water tank / motor\", \"New bathroom fitting\", \"Other\"], \"required\": true}]', 1, 1, 2, '2026-11-25 07:56:10', '2026-11-25 07:56:10'),
(4, 'AC Repair & Service', 'ac-repair-service', 'Service, gas refill, repair & installation', 'Keep cool with professional AC servicing, gas refill, repair, installation and uninstallation for all brands.', 'snowflake', 499.00, 'per AC', '[\"All brands, split & window\", \"Jet-pump deep cleaning\", \"Gas refill with pressure check\", \"Installation & uninstallation\"]', '[{\"key\": \"service_type\", \"type\": \"select\", \"label\": \"Service type\", \"options\": [\"Service / cleaning\", \"Gas refill\", \"Repair (not cooling, noise, leak)\", \"Installation\", \"Uninstallation\"], \"required\": true}, {\"key\": \"ac_type\", \"type\": \"select\", \"label\": \"AC type\", \"options\": [\"Split AC\", \"Window AC\", \"Cassette / central\", \"Not sure\"], \"required\": true}, {\"key\": \"units\", \"type\": \"number\", \"label\": \"Number of ACs\", \"required\": true, \"placeholder\": \"e.g. 1\"}]', 1, 1, 3, '2026-11-25 07:56:10', '2026-11-25 07:56:10'),
(5, 'Physiotherapy', 'physiotherapy', 'Certified physiotherapists at your home', 'Qualified physiotherapists for pain relief, post-surgery rehab, sports injuries and elderly care - in the comfort of your home.', 'heart', 699.00, 'per session', '[\"Qualified, experienced therapists\", \"Personalised treatment plan\", \"Home visits - no travel\", \"Session packages available\"]', '[{\"key\": \"concern\", \"type\": \"select\", \"label\": \"Main concern\", \"options\": [\"Back / neck pain\", \"Knee / joint pain\", \"Post-surgery rehabilitation\", \"Sports injury\", \"Stroke / neuro rehab\", \"Elderly care & mobility\", \"Other\"], \"required\": true}, {\"key\": \"patient_age\", \"type\": \"number\", \"label\": \"Patient age\", \"required\": true, \"placeholder\": \"e.g. 45\"}, {\"key\": \"sessions\", \"type\": \"select\", \"label\": \"Sessions needed\", \"options\": [\"1 session (assessment)\", \"5 sessions\", \"10 sessions\", \"Not sure yet\"], \"required\": false}, {\"key\": \"therapist_gender\", \"type\": \"select\", \"label\": \"Preferred therapist\", \"options\": [\"No preference\", \"Female\", \"Male\"], \"required\": false}]', 1, 1, 4, '2026-11-25 07:56:10', '2026-11-25 07:56:10'),
(6, 'Home Cleaning', 'home-cleaning', 'Deep cleaning for homes, kitchens & bathrooms', 'Trained cleaning teams with professional equipment for full-home, kitchen, bathroom and sofa deep cleaning.', 'sparkles', 399.00, 'onwards', '[\"Trained & background-checked staff\", \"Eco-friendly chemicals\", \"Machines & supplies included\", \"Satisfaction guaranteed\"]', '[{\"key\": \"cleaning_type\", \"type\": \"select\", \"label\": \"Cleaning type\", \"options\": [\"Full home deep cleaning\", \"Kitchen cleaning\", \"Bathroom cleaning\", \"Sofa / carpet cleaning\", \"Move-in / move-out cleaning\"], \"required\": true}, {\"key\": \"home_size\", \"type\": \"select\", \"label\": \"Home size\", \"options\": [\"1 BHK\", \"2 BHK\", \"3 BHK\", \"4 BHK+\", \"Villa / independent house\"], \"required\": false}]', 1, 1, 6, '2026-11-25 07:56:10', '2026-11-25 07:56:10'),
(7, 'Carpenter', 'carpenter', 'Furniture repair, assembly & fittings', 'Skilled carpenters for furniture repair and assembly, door and window fixes, and custom woodwork.', 'hammer', 199.00, 'per visit', '[\"Furniture assembly & repair\", \"Door, lock & hinge fixes\", \"Curtain rods & shelves\", \"Custom woodwork on request\"]', '[{\"key\": \"work_type\", \"type\": \"select\", \"label\": \"What do you need?\", \"options\": [\"Furniture repair\", \"Furniture assembly\", \"Door / lock / hinge\", \"Shelves / curtain rods\", \"Custom woodwork\", \"Other\"], \"required\": true}]', 1, 0, 7, '2026-11-25 07:56:10', '2026-11-25 07:56:10'),
(8, 'Appliance Repair', 'appliance-repair', 'Washing machine, fridge, RO, microwave & more', 'Repair and servicing for all major home appliances and brands, with genuine spare parts.', 'appliance', 249.00, 'per visit', '[\"All major brands\", \"Genuine spare parts\", \"Doorstep diagnosis\", \"Repair warranty\"]', '[{\"key\": \"appliance\", \"type\": \"select\", \"label\": \"Appliance\", \"options\": [\"Washing machine\", \"Refrigerator\", \"Water purifier (RO)\", \"Microwave\", \"Geyser\", \"Television\", \"Chimney\", \"Other\"], \"required\": true}, {\"key\": \"brand\", \"type\": \"text\", \"label\": \"Brand\", \"required\": false, \"placeholder\": \"e.g. LG, Samsung\"}]', 1, 0, 8, '2026-11-25 07:56:11', '2026-11-25 07:56:11'),
(9, 'Pest Control', 'pest-control', 'Cockroach, termite, bed bug & mosquito control', 'Safe, odourless and certified pest control treatments for homes and offices.', 'bug', 899.00, 'onwards', '[\"Government-approved chemicals\", \"Safe for kids & pets\", \"Odourless treatment\", \"Free follow-up visit\"]', '[{\"key\": \"pest\", \"type\": \"multiselect\", \"label\": \"Pest type\", \"options\": [\"Cockroaches\", \"Termites\", \"Bed bugs\", \"Mosquitoes\", \"Rodents\", \"Ants\"], \"required\": true}, {\"key\": \"home_size\", \"type\": \"select\", \"label\": \"Property size\", \"options\": [\"1 BHK\", \"2 BHK\", \"3 BHK\", \"4 BHK+\", \"Office / commercial\"], \"required\": false}]', 1, 0, 9, '2026-11-25 07:56:11', '2026-11-25 07:56:11'),
(10, 'Painting', 'painting', 'Interior & exterior painting, waterproofing', 'Professional painters for a fresh look - interior, exterior, texture and waterproofing, with free inspection.', 'brush', NULL, NULL, '[\"Free site inspection & quote\", \"Branded paints\", \"Furniture covered & cleaned up\", \"On-time completion\"]', '[{\"key\": \"paint_type\", \"type\": \"select\", \"label\": \"Painting type\", \"options\": [\"Interior\", \"Exterior\", \"Texture / design wall\", \"Waterproofing\", \"Wood polish\"], \"required\": true}, {\"key\": \"home_size\", \"type\": \"select\", \"label\": \"Area\", \"options\": [\"Single room\", \"1 BHK\", \"2 BHK\", \"3 BHK\", \"4 BHK+\", \"Commercial\"], \"required\": false}]', 1, 0, 10, '2026-11-25 07:56:11', '2026-11-25 07:56:11');
